static int Sod(int[] arr)
{
    int sum = 0;
    for (int i = 0; i < arr.Length; i++)
    {
        if (arr[i] % (i + 1) == 0)
            sum += arr[i];
    }
    return sum;
}
static void Main(string[] args)
{
    int[] arr = { 4, 8, 14, 45, 10, 11 };
    int s = Sod(arr);
    Console.WriteLine("s :=" + s);
}

static int Sod(int[] arr, int a, int b)
{
    int count = 0;
    for (int i = 0; i < arr.Length; i++)
    {
        if (arr[i] >= a && arr[i] <= b)
            count++;
    }
    return count;
}
static void Main(string[] args)
{
    int[] arr = { 4, 8, 14, 45, 10, 11 };
    int s = Sod(arr, 5, 12);
    Console.WriteLine("s :=" + s);
}

public static void Sod(int[] arr)
{
    int num1 = arr[0], num2 = arr[0]; //
    int num3 = 0, num4 = 0; //
    for (int i = 1; i < arr.Length; i++)
    {
        if (arr[i] > num1)
        {
            num1 = arr[i];
            num3 = i;
        }
        if (arr[i] < num2)
        {
            num2 = arr[i];
            num4 = i;
        }
    }
    int temp = arr[num3];
    arr[num3] = arr[num4];
    arr[num4] = temp;
}
static void Main()
{
    int[] numbers = { 3, 1, 5, 12, 2, 11, 7 };
    Sod(numbers);
}

